const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const APP_BASE=new URL('.',document.currentScript?.src||location.href);
const OFFLINE=!!window.__OFFLINE_DATA__;
let pages=[],routeLookup={},pageLookup={};
const slug=s=>String(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const nav=[['','⌂','Wiki home'],['spoilers','!','Spoilers'],['buildings','▤','Buildings'],['resources','◈','Resources'],['food','◉','Food'],['chains','⇄','Production chains'],['levels','⚑','Campaigns & levels'],['challenges','◇','Challenges'],['biomes','♧','Biomes'],['heroes','♙','Leaders'],['index','A–Z','All-pages index'],['verification','◌','Sources & research'],['contribute','+','Contribute'],['about','↗','Sources & artwork']];
let D,W,A,V,N,query='',filter='all',sort='name',limit=Infinity,section='',route='',id='',lastRoute='',showInternal=false;
const suppressedPages=new Set(['buildings/92319','chains/92319','buildings/field-orchard-base','chains/field-orchard-base']);
const isSuppressed=(type,id)=>suppressedPages.has(type+'/'+String(id));
let B,R,F,Bkey,Rkey,artBase=APP_BASE.pathname;
function url(type,id=''){
 const key=type+'/'+id;let path=pageLookup[key]?.path;
 if(!path)path=type==='chains'?'production-chains/':type?type+'/':'';
 if(OFFLINE)return '#/'+path;
 return APP_BASE.pathname+path;
}
function setupPages(){
 pages=[];routeLookup={};pageLookup={};const used=new Set;
 function add(type,id,name,category,path){
  if(isSuppressed(type,id))return;
  if(used.has(path))path=path.replace(/\/$/,'')+'-'+slug(id)+'/';used.add(path);
  const originalPath=path;if(spoilerEntry(type,id))path='spoilers/'+path;const rec={type,id:String(id),name,category,path,spoiler:!!spoilerEntry(type,id)};pages.push(rec);routeLookup[path]=rec;if(rec.spoiler)routeLookup[originalPath]=rec;pageLookup[type+'/'+id]=rec;return rec;
 }
 add('','','Outlanders 2 Wiki','Reference','');
 for(const [type,,name] of nav)if(type)add(type,'',name,'Directory',type==='chains'?'production-chains/':type+'/');
 for(const b of D.buildings){add('buildings',b.gameobject_id,b.name,'Building','buildings/'+slug(b.name)+'/');if(b.formula_ids.length)add('chains',b.gameobject_id,b.name+' — production','Production chain','production-chains/'+slug(b.name)+'/')}
 for(const r of D.resources){const food=r.publicly_named&&r.need_units.FoodUnits>0;add('resources',r.id,r.name,food?'Food':r.publicly_named?'Resource':'Intermediate',(food?'food/':'resources/')+slug(r.name)+'/')}
 for(const [type,items,label] of [['heroes',W.leaders,'Hero / leader'],['biomes',W.biomes,'Biome'],['levels',W.levels,'Level'],['campaigns',W.campaigns,'Campaign']])for(const x of items)add(type,x.id,x.name,label,type+'/'+slug(x.name)+'/');
 for(const rec of [...pages])if(rec.id&&['buildings','resources','chains','heroes','biomes','levels'].includes(rec.type))add('evidence',rec.type+'/'+rec.id,rec.name+' — research','Research','verification/'+rec.path);
 for(const old of W.legacy_routes||[]){const target=pageLookup[old.type+'/'+old.id];if(target&&!routeLookup[old.path])routeLookup[old.path]=target;}
 // Compatible aliases resolve to canonical pages; only canonical entries appear in the book index.
 for(const rec of pages){if(rec.type==='buildings'&&rec.id)routeLookup[rec.path.replace(/^buildings\//,'building/')]=rec;if(rec.category==='Food')routeLookup[rec.path.replace(/^food\//,'resources/')]=rec}
}
function readRoute(){
 let path=OFFLINE?location.hash.replace(/^#\/?/,''):decodeURIComponent(location.pathname.slice(APP_BASE.pathname.length));
 path=path.replace(/^\/+|\/+$/g,'');path=path?path+'/':'';
 if(routeLookup[path])return [routeLookup[path].type,routeLookup[path].id];
 const parts=path.split('/');if(parts[0]==='chains')parts[0]='chains';return parts;
}

const tag=(s,style='')=>`<span class="tag ${style}">${esc(s)}</span>`;
const unverified=()=>'';
const fmt=n=>Number.isInteger(n)?String(n):String(Math.round(n*1000)/1000);
function icon(type,entity,cls='',alt=''){let a;if(type==='buildings')a=A.buildings[entity.gameobject_id];if(type==='resources')a=A.resources[entity.id];if(type==='biomes')a=A.biomes[entity.id==='Green'?'Evergreen':entity.id];if(type==='heroes'){let k=Object.keys(A.leaders).find(k=>k===entity.name)||Object.keys(A.leaders).find(k=>k===entity.name+' A')||Object.keys(A.leaders).find(k=>k.startsWith(entity.name+' '));a=A.leaders[k]}return a?`<img ${cls?`class="${cls}"`:''} src="${artBase}${esc(a.path)}"${a.contrast_background?` style="background:${a.contrast_background};padding:5px;border-radius:4px"`:""} alt="${esc(alt)}" loading="lazy">`:`<span class="placeholder-icon" aria-hidden="true">${type==='heroes'?'♙':type==='biomes'?'♧':'◇'}</span>`}
function plain(s){return String(s||'').replace(/<[^>]*>/g,'').replace(/\{([^}]+)\}/g,(_,k)=>{const key=k.split('.').slice(0,2).join('.');return Bkey[key]?.name||Rkey[key]?.name||(k.toLowerCase()==='count'?'quantity to verify':k.split('.').slice(-1)[0])})}
function legacyRich(s){return esc(s||'').replace(/&lt;\/?(?:style(?:=[^&]*?)?|size(?:=[^&]*?)?)&gt;/g,'').replace(/&lt;(\/?)b&gt;/g,'<$1strong>').replace(/\n/g,'<br>').replace(/\{([^}]+)\}/g,(_,key)=>{const base=key.split('.').slice(0,2).join('.');if(Bkey[base])return `<a class="resource-link" href="${url('buildings',Bkey[base].gameobject_id)}">${esc(Bkey[base].name)}</a>`;if(Rkey[base])return `<a class="resource-link" href="${url('resources',Rkey[base].id)}">${esc(Rkey[base].name)}</a>`;if(/count|amount|days|value|percentage|name/i.test(key))return `<span class="missing" title="The requirement is a template; its value has not been decoded">${esc(key)}: not decoded</span>`;return `<span class="missing">${esc(key.replace(/^UI\./,'').replace(/\.WithIcon.*/,''))}</span>`})}
function source(s,title='View source evidence'){return `<details open class="source"><summary>${esc(title)}</summary><div class="source-body"><p>Recovered from game v30, build 254. A source match confirms the stored value; it does not confirm live gameplay behavior.</p><pre>${esc(JSON.stringify(s,null,2))}</pre></div></details>`}
function notice(title,text,green=false){return `<div class="notice ${green?'green':''}"><span aria-hidden="true">${green?'✓':'◌'}</span><div><strong>${esc(title)}</strong><p>${text}</p></div></div>`}
function header(title,sub,eye='REFERENCE'){return `<div class="page-header"><p class="eyebrow">${esc(eye)}</p><h1>${esc(title)}</h1><p class="lede">${esc(sub)}</p></div>`}
function crumbs(type,name){return `<div class="crumbs"><a href="#/">Wiki home</a><span>›</span><a href="${url(type)}">${esc(nav.find(x=>x[0]===type)?.[2]||type)}</a><span>›</span><span>${esc(name)}</span></div>`}
function matches(o){return !query||[o.name,o.internal_name,o.description,o.biography,o.effect,...(o.paths||[])].join(' ').toLowerCase().includes(query.toLowerCase())}
function category(b){return b.sleep_spots!==null?'homes':b.is_plant||/field|sapling|planter|tree pit/i.test(b.name)?'fields':b.formula_ids.length?'production':'other'}
function uniq(items,key=o=>o.name){let map=new Map;for(let x of items){let k=key(x);if(!map.has(k))map.set(k,{...x,variants:[]});map.get(k).variants.push(x)}return [...map.values()]}
function card(type,o){let name=o.name,subtitle='',meta='',img='',evidence=tag('Decoded data');let key=o.id;if(type==='buildings'){key=o.gameobject_id;img=icon(type,o);subtitle=plain(o.description).slice(0,110);meta=(o.max_workers!==null?`${o.max_workers} workers`:(o.sleep_spots!==null?`${o.sleep_spots} sleep spots`:'Building reference'))+(o.variants?.length>1?` · ${o.variants.length} variants`:'')}if(type==='resources'){img=icon(type,o);subtitle=o.publicly_named?'Resource values, recipes and related buildings.':'An internal production state or resource definition.';meta=o.publicly_named?'Named game resource':'Internal intermediate'}if(type==='chains'){key=o.gameobject_id;img=icon('buildings',o);subtitle=o.derived_recipes.find(r=>!r.caveats.length)?balanceText(o.derived_recipes.find(r=>!r.caveats.length)):'Explore the individual steps, inputs and outputs.';meta=`${o.formula_ids.length} formula steps`;evidence=tag('Derived from data')}if(type==='heroes'){img=icon(type,o);subtitle=plain(o.effect);meta='Hero / leader';evidence=tag('Game text')}if(type==='biomes'){img=icon(type,o);subtitle=o.rules_text.length?'Environmental needs and recovered help text.':'A named biome with original game artwork.';meta=o.rules_text.length?`${o.rules_text.length} help entries`:'Rules still being documented';evidence=tag('Game text')}if(type==='levels'){img=`<span class="placeholder-icon">⚑</span>`;subtitle=plain(o.description).slice(0,140);meta=o.category==='campaign'?`Campaign ${o.campaign_number}`:o.category==='tutorial'?'Tournament tutorial':'Map category unverified';evidence=tag('Objective templates')}return `<a class="card" href="${url(type,key)}"><div class="card-image ${type==='heroes'?'portrait':type==='biomes'?'landscape':''}">${img}</div><div class="card-body"><div>${evidence}</div><h3 style="margin-top:9px">${esc(name)}</h3><p>${esc(subtitle)}</p><div class="card-meta"><span>${esc(meta)}</span><span>↗</span></div></div></a>`}
function empty(){return `<div class="empty"><h2>No entries found</h2><p>Try a different search, or choose another category.</p><button class="button secondary" id="clear">Clear search & filters</button></div>`}
function resourceChip(r){let o=R[r.resource_id];return `<a class="requirement" href="${url('resources',r.resource_id||'unknown')}">${o?icon('resources',o):''}<span><strong>${fmt(r.count)}</strong> ${esc(r.name)}</span></a>`}
function amounts(rs){return rs.map(resourceChip).join('')||'<span class="small">No material inputs recorded for this step</span>'}
function balanceText(r){return r.inputs.map(x=>`${fmt(x.count)} ${x.name}`).join(' + ')+' → '+r.outputs.map(x=>`${fmt(x.count)} ${x.name}`).join(' + ')}
function balance(r){return `<div class="balance"><div><span class="balance-label">Material inputs</span><div class="balance-group">${amounts(r.inputs)}</div></div><span class="arrow">→</span><div><span class="balance-label">Finished output</span><div class="balance-group">${amounts(r.outputs)}</div></div></div>`}
function checks(items){return `<ul class="check-list">${items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`}
function asideFacts(entries){return `<aside class="detail-aside"><div class="panel"><h4>Properties</h4><dl class="definition">${entries.filter(x=>x[1]!==null&&x[1]!==undefined).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="tags">${unverified()}</div></div></aside>`}
function buildingPage(b){if(b.is_plant)return cropPage(b);let con=b.construction,w=b.workplace_config,same=D.buildings.filter(x=>x.name===b.name&&x.gameobject_id!==b.gameobject_id);return `${crumbs('buildings',b.name)}<div class="detail-head"><div class="detail-icon">${icon('buildings',b)}</div><div><p class="eyebrow">BUILDING REFERENCE</p><h1>${esc(b.name)}</h1><div class="tags">${tag('Decoded configuration')}${unverified()}</div></div></div><div class="detail-layout"><article>${buildingInfobox(b)}${verifyBadge('buildings',b.gameobject_id,W.ui_observations?.buildings?.[b.name]?'<span class="tag">Field guide checked in game</span>':'')}${observedBuilding(b)}<div class="prose">${b.description?`<p>${rich(b.description)}</p>`:'<p>No description was linked to this building definition.</p>'}</div><section class="rule-section"><h2>Construction inputs</h2>${con?.material_inputs.length?`<div class="requirements">${amounts(con.material_inputs)}</div><p class="small">Sum of distinct material formulas in the linked construction stages. Repeated stages and alternatives need gameplay verification.</p>`:notice('Construction cost not established','No material-bearing construction formula was recovered here. This does not mean the building is free.')} ${con?source({build_site:con.build_site_component_id,formula_ids:con.material_formula_ids,formulas:con.material_formula_ids.map(i=>F[i])},'Construction evidence'):''}</section>${b.formula_ids.length?`<section class="rule-section"><div class="section-top"><h2>Production</h2><a class="text-link" href="${url('chains',b.gameobject_id)}">Open full chain →</a></div>${b.derived_recipes.filter(r=>!r.caveats.length).map(balance).join('')||'<p class="small">The process has internal states, alternatives or source requirements that need interpretation. Explore the individual steps.</p>'}<a class="button secondary" href="${url('chains',b.gameobject_id)}">Production chain →</a></section>`:''}<section class="rule-section"><h2>Pending verification</h2>${checks(['Compare the construction inputs with the in-game building panel.','Confirm whether construction stages repeat or allow alternate materials.',...(b.max_workers!==null?['Confirm the staffing limit and measure output under controlled staffing.']:[]),...(b.sleep_spots!==null?['Confirm housing capacity, including separate baby and pet spaces.']:[]),'Check whether this variant is available in normal gameplay.'])}</section>${same.length?`<section class="rule-section"><h2>Other definitions with this name</h2><p class="small">These variants have separate source records. Their menu availability is unverified.</p><div class="variant-list">${same.map(x=>`<a href="${url('buildings',x.gameobject_id)}">${esc(x.internal_name)} · ${x.gameobject_id}</a>`).join('')}</div></section>`:''}${objectiveBacklinks(b.name,objectiveTargets(o=>o.target?.gameobject_id===b.gameobject_id||o.building?.gameobject_id===b.gameobject_id&&o.condition_name==='HaveInBuilding'))}${scenarioBacklinks(b)}${availabilitySection('buildings',b)}${source({building:b.source,workplace:b.workplace_source,content_paths:b.paths,dimensions:b.dimensions,workplace_config:w,placement_rules:b.placement_rules})}${navbox('buildings',b)}</article>${asideFacts([['Data version','30 · build 254'],['Entry type',category(b)],['Internal name',b.internal_name],['Footprint (raw dimensions)',b.dimensions?`${b.dimensions.x} × ${b.dimensions.z}`:null],['Work range (raw units)',w?`${fmt(w.WorkTimeRange.Start)} → ${fmt(w.WorkTimeRange.End)}`:null],['Game verification','Pending']])}</div>`}
function chainPage(b){let fs=b.formula_ids.map(i=>F[i]).filter(Boolean),good=b.derived_recipes.filter(r=>!r.caveats.length),complex=b.derived_recipes.filter(r=>r.caveats.length);return `${crumbs('chains',b.name)}<div class="detail-head"><div class="detail-icon">${icon('buildings',b)}</div><div><p class="eyebrow">PRODUCTION CHAIN</p><h1>${esc(b.name)}</h1><div class="tags">${tag('Derived from decoded steps')}${unverified()}</div></div></div><p class="lede">Trace the material transformations inside the ${esc(b.name)}. Step order below follows source IDs, not a verified execution schedule.</p>${notice('Material balance, not production speed','These ratios eliminate intermediate states. Worker availability, equipment, storage, hauling and animation timing still need gameplay checks.')}<div class="detail-layout"><article>${verifyBadge('chains',b.gameobject_id)}${observedBuilding(b)}<section class="rule-section"><h2>Recovered material balance</h2>${good.map(balance).join('')||'<p class="small">A complete balance has not been established. Read the individual steps below; alternatives and non-material processes may be involved.</p>'}${complex.length?notice('Some branches need interpretation','This chain includes alternate producers, extraction sources, internal prerequisites, partial outputs or other unresolved behavior. See the full evidence below.'):''}</section><section class="rule-section"><h2>Formula steps</h2><details><summary>Show the ${fs.length} decoded steps</summary><ol class="step-list">${fs.map(f=>`<li><div class="requirements">${amounts(f.inputs)}<span class="arrow">→</span>${f.outputs.length?amounts(f.outputs):'<span class="small">Work / construction action</span>'}</div><span class="small">Formula ${f.id}${f.required_equipment_category_id?' · Equipment required':''}${f.work_iterations?' · '+f.work_iterations+' work iterations':''}${f.partial_output?' · Partial output':''}${!f.referencing_workspot_ids.length?' · Workspot linkage not established':''}</span></li>`).join('')}</ol></details></section><section class="rule-section"><h2>Gameplay checks</h2>${checks(['Observe a full production cycle and compare actual materials consumed and produced.','Verify whether all recovered branches are active for this building.','Measure timing with a fixed workforce and nearby storage.','Check equipment requirements, capacity limits and unused leftovers.'])}</section>${source({formulas:fs,derived_balances:b.derived_recipes})}</article>${asideFacts([['Building',b.name],['Maximum workers',b.max_workers],['Formula steps',fs.length],['Throughput','Not measured'],['Execution order','Not verified']])}</div><a class="button secondary" href="${url('buildings',b.gameobject_id)}">← Building reference</a>`}
function resourcePage(r){const producing=D.buildings.filter(b=>b.formula_ids.some(i=>F[i]?.outputs.some(x=>x.resource_id===r.id))),using=D.buildings.filter(b=>b.formula_ids.some(i=>F[i]?.inputs.some(x=>x.resource_id===r.id))),costs=D.buildings.filter(b=>b.construction?.material_inputs.some(x=>x.resource_id===r.id)),vals=Object.entries(r.need_units).filter(([,v])=>v!==0),objectives=r.localization_key?objectiveTargets(o=>o.target?.localization_key===r.localization_key):[];function related(bs){return `<div class="article-list">${uniq(bs).map(b=>`<a href="${url('buildings',b.gameobject_id)}">${icon('buildings',b)}<span>${esc(b.name)}</span><small>View building ↗</small></a>`).join('')}</div>`}return `${crumbs('resources',r.name)}<div class="detail-head"><div class="detail-icon">${icon('resources',r)}</div><div><p class="eyebrow">${r.publicly_named?'RESOURCE':'INTERNAL RESOURCE / INTERMEDIATE'}</p><h1>${esc(r.name)}</h1><div class="tags">${tag('Decoded data')}${unverified()}</div></div></div>${!r.publicly_named?notice('An internal production state','This definition may exist only within a multi-step process. It is not established as a stockpile item or a player-facing resource.'):''}<div class="detail-layout"><article>${resourceInfobox(r,producing,using,costs,objectives)}${verifyBadge('resources',r.id)}<section class="rule-section"><h2>Configured satisfaction values</h2>${vals.length?`<div class="fact-grid">${vals.map(([k,v])=>`<div class="fact"><small>${esc(k.replace('Units',' units'))}</small><b>${fmt(v)}</b><small>Stored configuration</small></div>`).join('')}</div><p class="small">These are internal units. Direct gauge increases, consumption frequency and runtime multipliers have not been verified.</p>`:'<p class="small">No nonzero satisfaction values are stored on this definition.</p>'}</section>${producing.length?`<section class="rule-section"><h2>Produced by</h2>${related(producing)}</section>`:''}${using.length?`<section class="rule-section"><h2>Used in production</h2>${related(using)}</section>`:''}${costs.length?`<section class="rule-section"><h2>Used in construction</h2>${related(costs)}</section>`:''}${objectives.length?`<div id="objective-backlinks">${objectiveBacklinks(r.name,objectives)}</div>`:''}${!producing.length&&!using.length&&!costs.length?notice('No linked building process','This resource is not linked to a recovered building formula. Gathering, trading or other sources may still apply.'):''}<section class="rule-section"><h2>Pending verification</h2>${checks(['Confirm that this item or intermediate is used in the installed game.','Verify the displayed recipe quantities and any satisfaction effects.','Check for alternate recipes, trade sources and scenario-specific behavior.'])}</section>${source(r)}${navbox('resources',r)}</article>${asideFacts([['Internal name',r.internal_name],['Resource type',r.publicly_named?'Named resource':'Internal definition'],['Produced by',uniq(producing).length+' buildings'],['Used in construction',uniq(costs).length+' buildings'],['Gameplay verification','Pending']])}</div>`}
function worldPage(type,o){let bio=type==='heroes',biome=type==='biomes';return `${crumbs(type,o.name)}<div class="detail-head">${bio?icon(type,o,'detail-portrait',o.name):biome?icon(type,o,'detail-landscape',o.name):'<div class="detail-icon"><span class="placeholder-icon">⚑</span></div>'}<div><p class="eyebrow">${bio?'HERO / LEADER':biome?'BIOME':'LEVEL REFERENCE'}</p><h1>${esc(o.name)}</h1><div class="tags">${tag(o.scenario?'Decoded scenario + game text':'Recovered game text')}${availability(type,o)}${unverified()}</div></div></div><div class="detail-layout"><article>${verifyBadge(type,o.id)}${!bio&&!biome?storyContext(o):''}${bio?`<div class="prose"><p>${rich(o.biography)}</p></div><section class="rule-section"><h2>Leader effect</h2><div class="hero-quote">${rich(o.effect||'No effect description recovered.')}</div>${notice('Effect magnitude not established','This is the game’s description of the effect. Strength, duration, stacking and applicability have not been decoded or tested.')}</section><section class="rule-section"><h2>Gameplay checks</h2>${checks(['Verify the effect under controlled conditions.','Measure the bonus magnitude and test whether it applies to all villagers or only a region.','Confirm portrait and leader variant availability.'])}</section>${leaderStories(o)}`:biome?biomeBody(o):levelBody(o)}${bio?availabilitySection('heroes',o):!biome?availabilitySection('levels',o):''}${source(bio?o.source_entries:biome?[o.source,...o.rules_text]:{id:o.id,verification_status:o.verification_status,source_entries:o.source_entries},'Recovered text & source identifiers')}${navbox(type,o)}</article>${asideFacts(bio?[['Game terminology','Leader'],['Effect source','Localized description'],['Numeric bonus','Not decoded'],['Gameplay verification','Pending']]:biome?[['Internal biome ID',o.id],['Crop assignments',biomeRule(o)?.source?'Sandbox data decoded':'Not established'],['Level assignments','Overrides unverified']]:[['Level identifier',o.id],['Category',o.category==='standalone_or_challenge'?'Standalone / challenge unverified':o.category],['Campaign',o.campaign_number],['Objective quantities',o.scenario?'Decoded and cross-checked':'Not decoded'],['Packaged map',o.packaged_level_text_asset_id?'Present':'Not linked']])}</div>`}
function legacyLevelBody(o){let groups=new Map;for(let v of o.objectives){if(!groups.has(v.id))groups.set(v.id,[]);if(!groups.get(v.id).some(x=>x.text===v.text))groups.get(v.id).push(v)}return `<div class="prose"><p>${rich(o.description)}</p></div>${notice('Objective quantities are not decoded','Any count shown as “not decoded” is a placeholder, not a requirement of zero. Packaged source tables sometimes contain alternate objective text.')}<section class="rule-section"><h2>Recovered objectives</h2>${groups.size?[...groups].map(([k,vs])=>`<div class="objective"><span>${esc(k.replace(/Objective\./,'').replaceAll('.',' · '))}</span>${vs.map((v,i)=>`<p>${vs.length>1?tag('Text version '+(i+1),'gray')+' ':''}${rich(v.text)}</p>`).join('')}${vs.length>1?'<small class="small">Source tables disagree. The active objective text needs checking in game.</small>':''}</div>`).join(''):'<p class="small">No objective text has been recovered for this level.</p>'}</section><section class="rule-section"><h2>Pending verification</h2>${checks(['Read the active objective counts and day limits in game.','Confirm the level’s campaign or challenge placement and current availability.','Record biome, starting villagers, resources and unlocked buildings.','Resolve alternate objective text against the installed game.'])}</section>`}
function challenges(){const entries=W.challenges.source_entries.filter(e=>/Description|Help|Objective/.test(e.key));const unique=uniq(entries,e=>e.english).filter(e=>!query||plain(e.english+' '+e.key).toLowerCase().includes(query.toLowerCase()));return `${header('Challenges','Recovered challenge and tournament help, objective templates and candidate maps. Archive categories and representative briefings have been inspected. Live scheduling and scoring remain unverified.','PLAY MODES')}<p class="small">Original, Redux, Bounty, Chill, Ranked and Remix are confirmed archive categories.</p>${challengeObservations()}${notice('No live challenge schedule is available','The installed data contains challenge text and maps, but it does not establish today’s rotation, leaderboard or active event.')}<div class="home-bottom"><div class="panel"><h2>Challenge map candidates</h2><p>Some packaged maps may belong to standalone or challenge menus. Their exact placement is unverified.</p><a class="button secondary" href="#/levels">Browse recovered maps →</a></div><div class="panel"><h2>FastMode supply chains</h2><p>${D.fastmode_supply_chain_validation.length} recovered rules describe which resource combinations the level validator accepts. They are not ordinary construction costs.</p><a class="text-link" href="#/verification">Read the evidence limits →</a></div></div><section class="rule-section"><h2>Recovered mode help & objectives</h2><p class="small">${unique.length} unique text entries${query?' matching your search':''}. Numeric values may remain unresolved.</p>${unique.slice(0,limit).map(e=>`<div class="objective"><span>${esc(e.key)}</span><p>${rich(e.english)}</p><small class="small">Text asset ${e.source_text_asset_id}</small></div>`).join('')}${unique.length>limit?'<button class="button secondary show-more" id="more">Show more text ↓</button>':''}</section>${source(W.challenges.verification_status)}`}
function verification(){return `<section class="rule-section"><h2>Article research notes</h2><p>Sources, open questions and technical fields have moved here from the reader pages.</p><details open><summary>Browse article evidence</summary><ul>${pages.filter(p=>p.type==='evidence'&&!spoilerEntry(p.id.split('/')[0],p.id.slice(p.id.indexOf('/')+1))).map(p=>`<li><a href="${url('evidence',p.id)}">${esc(p.name)}</a></li>`).join('')}</ul></details><h2>New findings</h2><p>The three batch-08 localization entries are resolved to their batch-09 map files. Clay Pit and Farm have different stored work schedules; the claim that clay workers sleep longer remains unconfirmed. Pumpkin is explicitly referenced by Tropical sandbox configuration, but that reference alone does not establish gameplay availability.</p></section>${header('The verification ledger','Menu structure, example objectives and selected field-guide values have been checked in game. Controlled production cycles and runtime effects remain unverified.','EVIDENCE & OPEN QUESTIONS')}${challengeObservations()}${notice('Scenario extraction verified','438 objective records independently match their world copies. All 6,616 build-list entries resolve. Need flags are read using each map’s own stored layout.',true)}${notice('Decode checks passed; runtime checks are pending','1,800 definitions reproduce the original bytes exactly, including all 692 formula steps. That validates the decoder, not runtime behavior.',true)}<div class="verify-grid">${[['Stored configuration','Decoded data',['Building worker limits, linked construction formulas and resource satisfaction fields.','Formula inputs, outputs and intermediate states.','No assumption that every packaged definition is used.']],['Material balances','Derived from data',['Intermediate states are removed algebraically where the graph is unambiguous.','Timing, hauling, equipment wear and leftovers are not production-rate claims.','Complicated branches remain marked as needing interpretation.']],['World & people','Recovered game text',['438 objective records cross-checked between level headers and world data; scenario build lists and need flags decoded.','Story order was checked in the campaign menu; most story-to-level mappings still use identifiers.','Hero bonus strength, runtime unlocks, missing legacy need defaults and menu availability need testing.']],['Unresolved behavior','Needs gameplay verification',['Construction stage repetition and alternative materials.','Worker priorities, hauling distance, storage bottlenecks and effective throughput.','Need decay, leader effects, biome modifiers and growth timing.']]].map(([t,l,items])=>`<div class="panel">${tag(l,l.includes('Needs')?'amber':'')}<h2 style="margin-top:14px">${t}</h2>${checks(items)}</div>`).join('')}</div><section class="rule-section"><h2>Good first experiments</h2><div class="article-list">${['Bakery','Sawmill','Windmill'].map(n=>D.buildings.find(b=>b.name===n)).map(b=>`<a href="${url('chains',b.gameobject_id)}">${icon('buildings',b)}<span>${b.name}: costs, ratios and a complete cycle</span><small>Open chain ↗</small></a>`).join('')}</div></section><section class="rule-section"><h2>Contributing an observation</h2><p class="lede">Record the game version, level, biome, leader, staffing, storage distance and elapsed game time. Keep screenshots of the setup and outcome. An observation should update the specific claim it tests.</p></section>${source(D.manifest.decoder_validation,'Decoder validation summary')}`}
function about(){return `${header('Sources, data & artwork','An unofficial fan reference built from the installed Mac version of Outlanders 2.','ABOUT THIS WIKI')}<div class="prose"><h2>Traceable by design</h2><p>Building and resource pages link to source object IDs. Production chains retain every formula step used in their material balance. World entries retain localization keys and source text identifiers.</p><p>Recovered from game <strong>version 30, build 254</strong>. Packaged content can include unused definitions and alternate variants. UI observations are recorded separately from controlled gameplay tests, which remain pending.</p><h2>In-game field guide</h2><p>The game’s field guide supplies player-facing descriptions, displayed recipes, construction costs and worker slots. Bakery, Windmill, Sawmill and Greenhouse entries have been inspected, with screenshots linked from their pages. Scenario binaries provide exact objectives, build lists and need switches. Differences between displayed recipes and decoded process balances are retained in the research section; neither is treated as a measured production rate.</p><h2>Original game artwork</h2><p>The wiki uses <strong>80 extracted game icons, 45 static leader portrait variants and six biome previews</strong>. Icons use unchanged original line sprites; portraits and biome images retain their original colors. Runtime color composition has not been reproduced. Some building symbols depict their output, as in the game UI.</p><p>Outlanders 2 and its artwork are credited to <strong>Pomelo Games</strong>. This wiki is unofficial and is not affiliated with or endorsed by the developer. Extracted artwork is not offered under an open-source code license.</p><h2>Portable and static</h2><p>The site has no server-side dependency. It can run on GitHub Pages at a repository URL or a custom domain. Every published URL has its own static page file, including readable entry paths such as /buildings/bakery/ and /food/bread/.</p><h2>Scenario extraction</h2><p>285 packaged maps decoded, including tests. All 438 objective records match their independent world copies. Build/plant lists and explicit villager-need flags are shown per scenario; absent legacy fields remain unspecified.</p><h2>Download the evidence</h2><div class="requirements"><a class="button secondary" href="./data/rules.json" download>Rules dataset ↓</a><a class="button secondary" href="./data/scenarios.json" download>Scenario dataset ↓</a><a class="button secondary" href="./data/world.json" download>World catalog ↓</a><a class="button secondary" href="./data/manifest.json" download>Extraction manifest ↓</a><a class="button secondary" href="./data/validation.json" download>Decoder checks ↓</a></div><h2>Remaining limits</h2>${checks(D.manifest.limitations)}</div>${source(A.provenance,'Artwork extraction provenance')}`}
function render(){let parts=readRoute();route=parts[0]||'';id=decodeURIComponent(parts[1]||'');applySpoilerScope(route,id);section=(spoilerEntry(route,id)||route==='evidence'&&spoilerEntry(id.split('/')[0],id.slice(id.indexOf('/')+1)))?'spoilers':route==='campaigns'?'levels':route==='resources'&&id&&R[id]?.publicly_named&&R[id]?.need_units.FoodUnits>0?'food':route;let key=route+'/'+id;if(key!==lastRoute){filter='all';limit=Infinity;sort='name';showInternal=false;lastRoute=key}$('#nav').innerHTML=nav.map(([r,i,l],index)=>`${index===8||r==='spoilers'?'<div class="nav-divider"></div>':''}<a class="nav-link ${section===r?'active':''}" href="${url(r)}" ${section===r?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${i}</span>${l}</a>`).join('');let html='',title='Wiki home';if(isSuppressed(route,id)){html=header('Entry not found','This link does not match a published entry.');title='Entry not found'}else if(!route){html=query?searchAll():home()}else if(route==='buildings'&&id&&B[id]){html=buildingPage(B[id]);title=B[id].name}else if(route==='chains'&&id&&B[id]){html=chainPage(B[id]);title=B[id].name+' production chain'}else if(route==='resources'&&id&&R[id]){html=resourcePage(R[id]);title=R[id].name}else if(['heroes','biomes','levels'].includes(route)&&id){let items=route==='heroes'?W.leaders:W[route],o=items.find(x=>x.id===id);html=o?worldPage(route,o):empty();title=o?.name||'Entry not found'}else if(route==='campaigns'&&id){let c=W.campaigns.find(c=>c.id===id);html=c?campaignPage(c):empty();title=c?.name||'Campaign'}else if(route==='index'){html=bookIndex();title='All-pages index'}else if(['buildings','resources','food','chains','levels','heroes','biomes'].includes(route)&&!id){html=directory(route);title=nav.find(x=>x[0]===route)[2]}else if(route==='challenges'){html=challenges();title='Challenges'}else if(route==='evidence'){html=researchPage(id);title='Sources & research'}else if(route==='spoilers'){html=spoilersPage();title='Spoilers'}else if(route==='contribute'){html=contributionPage();title='Contribute'}else if(route==='verification'){html=verification();title='Verification ledger'}else if(route==='about'){html=about();title='Sources & artwork'}else{html=header('Entry not found','This link does not match a recovered entry.')+'<a href="#/" class="button">Return to the wiki</a>';title='Entry not found'}if(!isSuppressed(route,id)&&id&&['buildings','resources','chains','heroes','biomes','levels'].includes(route))html=readerArticle(html,route,id);if(spoilerEntry(route,id))html=spoilerWarning(route,id)+html;html=html.replace(/href="#\/([^"]*)"/g,(_,p)=>{const clean=p.replace(/^\/+|\/+$/g,'');const record=routeLookup[clean?clean+'/':''];if(record)return 'href="'+url(record.type,record.id)+'"';let [type,id]=p.split('/');return 'href="'+url(type||'',id||'')+'"'}).replace(/href="\.\/data\//g,'href="'+APP_BASE.pathname+'data/');$('#content').innerHTML=html;document.title=title+' · Outlanders 2 Wiki';let select=$('#sort');if(select){select.value=sort;select.onchange=()=>{sort=select.value;render()}}document.querySelectorAll('[data-filter]').forEach(btn=>btn.onclick=()=>{filter=btn.dataset.filter;showInternal=filter==='internal';limit=Infinity;render()});document.querySelectorAll('[data-letter]').forEach(b=>b.onclick=()=>document.getElementById('letter-'+b.dataset.letter)?.scrollIntoView({block:'start'}));if($('#more'))$('#more').onclick=()=>{limit+=60;render()};if($('#clear'))$('#clear').onclick=()=>{query='';$('#search').value='';filter='all';showInternal=false;render()}}
async function start(){try{[D,W,A,V,N]=await Promise.all(['rules','world','artwork','availability','biomes'].map(n=>fetch(new URL('data/'+n+'.json',APP_BASE).href).then(r=>{if(!r.ok)throw new Error('Missing data file: '+n);return r.json()})));B=Object.fromEntries(D.buildings.map(b=>[b.gameobject_id,b]));R=Object.fromEntries(D.resources.map(r=>[r.id,r]));F=Object.fromEntries(D.formulas.map(f=>[f.id,f]));initializeSpoilers();setupPages();Bkey=Object.fromEntries(D.buildings.filter(x=>x.localization_key).map(x=>[x.localization_key,x]));Rkey=Object.fromEntries(D.resources.filter(x=>x.localization_key).map(x=>[x.localization_key,x]));render();$('.skip').onclick=e=>{e.preventDefault();$('#content').focus()};addEventListener('hashchange',()=>{if(!OFFLINE)return;query='';$('#search').value='';document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');render();scrollTo(0,0)});let timer;$('#search').oninput=e=>{query=e.target.value;limit=Infinity;clearTimeout(timer);timer=setTimeout(render,100)};$('#menu').onclick=()=>{let open=document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',String(open))};addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}if(e.key==='Escape'){$('#search').blur();document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false')}})}catch(e){$('#content').innerHTML=header('The guide could not load','Please reload the page. This site needs to be served over HTTP rather than opened as a local file.')+`<p class="small">${esc(e.message)}</p>`}}
start();
function inlineAmounts(items){return items.map(x=>`<a class="resource-link" href="${url('resources',x.resource_id)}">${fmt(x.count)} ${esc(x.name)}</a>`).join(' + ')||'—'}
function catalogTable(type,items){
 let heads=type==='buildings'?['Building','Type','Construction inputs','Workers','Housing','Produces','Availability']:type==='resources'||type==='food'?['Resource','Satisfaction values','Type','Availability']:type==='chains'?['Building','Inputs','Outputs','Steps','Availability']:type==='heroes'?['Leader','Description of effect','Availability']:type==='biomes'?['Biome','Crops & resources','Needs / hazards','Availability']:['Level','Category','Objectives','Day limit','Build / plant entries','Enabled needs','Availability'];
 const rows=items.map(o=>{let key=type==='buildings'||type==='chains'?o.gameobject_id:o.id,kind=type==='food'?'resources':type;let cells=[];
 const name=`<a class="catalog-name" href="${url(kind,key)}">${icon(kind==='chains'?'buildings':kind,o)}<span>${esc(o.name)}${o.variants?.length>1?`<small>${o.variants.length} definitions</small>`:''}</span></a>`;
 if(type==='buildings'){const recipe=o.derived_recipes.find(r=>!r.caveats.length);cells=[name,o.is_plant?'Plant':CATEGORY_LABELS[category(o)].replace(' building',''),o.is_plant?'—':o.construction?.material_inputs.length?inlineAmounts(o.construction.material_inputs):'—',o.is_plant?'—':o.max_workers??'—',o.is_plant?'—':o.sleep_spots??'—',recipe?inlineAmounts(recipe.outputs):o.formula_ids.length?`<a href="${url('chains',o.gameobject_id)}">See chain</a>`:'—',availability('buildings',o)]}
 if(type==='resources'||type==='food')cells=[name,Object.entries(o.need_units).filter(([,v])=>v).map(([k,v])=>`${esc(k.replace('Units',''))}: ${fmt(v)}`).join('; ')||'—',o.publicly_named?'Named resource':'Intermediate',availability('resources',o)];
 if(type==='chains'){const recipe=o.derived_recipes.find(r=>!r.caveats.length);cells=[name,recipe?inlineAmounts(recipe.inputs):'<span class="unknown">See individual steps</span>',recipe?inlineAmounts(recipe.outputs):'—',o.formula_ids.length,availability('buildings',o)]}
 if(type==='heroes')cells=[name,rich(o.effect),availability(type,o)];
 if(type==='biomes'){const info=biomeRule(o),special={Green:'Default / baseline',Desert:'Thirst / hydration',Tropical:'Cooling / high temperatures',Winter:'Heat / cold'};cells=[name,'See scenario planting lists',special[o.id]||'Not established',availability(type,o)]}
 if(type==='levels')cells=[`<a href="${url(type,key)}">${esc(o.name)}</a>`,o.category==='campaign'?'Campaign '+o.campaign_number:o.id.startsWith('FAST_')?'Tutorial':'Menu category unverified',o.scenario?`${o.scenario.primary_objective_count} main / ${o.scenario.optional_objective_count} optional`:new Set(o.objectives.map(x=>x.id)).size+' templates',o.scenario?(o.scenario.day_limit===-1?'No limit stored':o.scenario.day_limit??'Unspecified'):'Not decoded',o.scenario?new Set(o.scenario.buildable_entries.map(x=>x.guid)).size:'Not decoded',o.scenario?scenarioNeedSummary(o.scenario):'Not decoded',availability(type,o)];
 return '<tr>'+cells.map(x=>'<td>'+x+'</td>').join('')+'</tr>';
 }).join('');return `<div class="table-wrap catalog-table"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`;
}
function directory(type){
 let items=[],title='',sub='',tabs=[];
 if(type==='buildings'){items=uniq(D.buildings.filter(b=>!isSuppressed('buildings',b.gameobject_id)));title='Buildings';sub='Construction material inputs, worker limits, housing capacity and production.';tabs=[['all','All'],['production','Production'],['homes','Housing'],['fields','Fields & plants'],['other','Other']];if(filter!=='all')items=items.filter(b=>category(b)===filter)}
 if(type==='resources'||type==='food'){items=uniq(D.resources.filter(r=>type==='food'?r.publicly_named&&r.need_units.FoodUnits>0:showInternal||r.publicly_named),r=>r.publicly_named?r.name:r.id);title=type==='food'?'Food':'Resources';sub=type==='food'?'Food values, producers and recipe inputs.':'Resource values, producers, consumers and construction uses.';if(type==='resources')tabs=[['all','Named resources'],['internal','Include intermediates']]}
 if(type==='chains'){items=uniq(D.buildings.filter(b=>b.formula_ids.length&&!isSuppressed('chains',b.gameobject_id)));title='Production chains';sub='Inputs, outputs and intermediate steps. Ratios are derived from stored formulas; throughput is unverified.';tabs=[['all','All'],['complete','Complete balances'],['complex','Unresolved balances']];if(filter==='complete')items=items.filter(b=>b.derived_recipes.some(r=>!r.caveats.length));if(filter==='complex')items=items.filter(b=>!b.derived_recipes.some(r=>!r.caveats.length))}
 if(type==='heroes'){items=W.leaders;title='Leaders';sub='Biographies, effect descriptions and content availability. Numeric bonus values are not established.'}
 if(type==='biomes'){items=W.biomes;title='Biomes';sub='Crops, resources, needs and hazards. Evergreen is the default comparison biome.'}
 if(type==='levels'){items=W.levels;title='Campaigns & levels';sub='Exact objectives, day limits, build and plant lists, and villager needs from scenario files. Live menu availability is labeled separately.';tabs=[['all','All'],['campaign','Campaigns'],['standalone_or_challenge','Other maps'],['tutorial','Tutorials']];if(filter!=='all')items=items.filter(o=>filter==='tutorial'?o.id.startsWith('FAST_'):o.category===filter)}
 items=items.filter(matches);items.sort(sort==='workers'?(a,b)=>(b.max_workers||0)-(a.max_workers||0):(a,b)=>a.name.localeCompare(b.name));
 return `${header(title,sub,'CATALOG')}${type==='levels'?`<div class="tabs campaign-links">${W.campaigns.map(c=>`<a class="tab" href="${url('campaigns',c.id)}">${esc(c.name)} (${c.level_ids.length})</a>`).join('')}</div>`:''}<div class="toolbar"><div class="tabs">${tabs.map(([k,t])=>`<button class="tab ${(type==='resources'?(showInternal?k==='internal':k==='all'):filter===k)?'active':''}" data-filter="${k}">${esc(t)}</button>`).join('')}</div><label class="small">Sort <select id="sort"><option value="name">Name A–Z</option>${type==='buildings'?'<option value="workers">Worker limit</option>':''}</select></label></div><p class="result-count">${items.length} entries${query?` matching “${esc(query)}”`:''} </p>${items.length?catalogTable(type,items.slice(0,limit)):empty()}${items.length>limit?'<button class="button secondary show-more" id="more">Show more entries</button>':''}`;
}
function home(){
 const groups=[['Buildings','buildings',uniq(D.buildings.filter(b=>!isSuppressed('buildings',b.gameobject_id)))],['Resources','resources',uniq(D.resources.filter(r=>r.publicly_named))],['Food','food',uniq(D.resources.filter(r=>r.publicly_named&&r.need_units.FoodUnits>0))],['Production chains','chains',uniq(D.buildings.filter(b=>b.formula_ids.length&&!isSuppressed('chains',b.gameobject_id)))],['Leaders','heroes',W.leaders],['Biomes','biomes',W.biomes],['Campaigns','campaigns',W.campaigns],['Levels','levels',W.levels]];
 return `${header('Outlanders 2 Wiki','Buildings, resources, production, maps and game rules.','REFERENCE')}<div class="catalog-summary">Version 30 · build 254 · ${D.buildings.length} building definitions · ${W.levels.length} maps · <a href="${url('index')}">All-pages A–Z index (${pages.length})</a></div><div class="category-index">${groups.map(([title,type,items])=>`<section class="index-group"><h2><a href="${url(type==='campaigns'?'levels':type)}">${title}</a><small>${items.length}</small></h2><ul>${[...items].sort((a,b)=>a.name.localeCompare(b.name)).slice(0,18).map(o=>`<li><a href="${url(type==='food'?'resources':type,o.gameobject_id||o.id)}">${esc(o.name)}</a>${o.name==='Oona'?' '+availability('heroes',o):''}</li>`).join('')}</ul>${items.length>18?`<a class="text-link" href="${url(type)}">All ${title.toLowerCase()} →</a>`:''}</section>`).join('')}</div><section class="rule-section"><h2>Reference</h2><div class="reference-links"><a href="${url('challenges')}">Challenges</a><a href="${url('verification')}">Verification ledger</a><a href="${url('about')}">Sources & artwork</a><a href="${url('index')}">Alphabetical page index</a></div></section>${spoilersHomeSection()}`;
}
function bookIndex(){
 const records=pages.filter(p=>p.type!=='evidence'&&!p.spoiler).filter(p=>!query||(p.name+' '+p.category+' '+p.path).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name)||a.category.localeCompare(b.category));
 const groups=new Map;for(const p of records){const letter=/[a-z]/i.test(p.name[0])?p.name[0].toUpperCase():'#';if(!groups.has(letter))groups.set(letter,[]);groups.get(letter).push(p)}
 return `${header('All-pages index','Alphabetical index of every canonical article and directory. Variants have separate entries; compatible URL aliases are omitted.','A–Z REFERENCE')}<p class="result-count">${records.length} of ${pages.length} pages. Use the alphabetical links or your browser’s Find command.</p><div class="alphabet">${[...groups.keys()].map(l=>`<a class="tab" href="#letter-${l}">${l}</a>`).join('')}</div><div class="book-index">${[...groups].map(([l,entries])=>`<section id="letter-${l}"><h2>${l}</h2><ul>${entries.map(p=>`<li><a href="${url(p.type,p.id)}">${esc(p.name)}</a>${p.type==='heroes'&&p.id==='Oona.000'?'<span class="tag violet">Unreleased · user report</span>':''}<span>${esc(p.category)}</span><small>/${esc(p.path)}</small></li>`).join('')}</ul></section>`).join('')}</div>`;
}
function campaignPage(c){const stories=W.stories.filter(s=>s.campaign_id===c.id).sort((a,b)=>a.menu_order-b.menu_order);const assigned=new Set(stories.flatMap(s=>s.level_ids||[]));const other=c.level_ids.filter(i=>!assigned.has(i)).map(i=>W.levels.find(l=>l.id===i)).filter(Boolean);return `${crumbs('levels',c.name)}${header(c.name,'Campaigns contain stories of three levels focused on a leader or town. Story order below was observed in the game menu.','CAMPAIGN')}${stories.map(s=>{const leader=W.leaders.find(l=>l.name===s.leader_name);return `<section class="rule-section"><h2>${s.menu_order}. ${esc(s.name)}</h2>${leader?`<p>Leader: <a href="${url('heroes',leader.id)}">${esc(leader.name)}</a></p>`:''}<p class="small">${s.level_mapping_status==='menu_verified'?'Level order checked in game.':'Level grouping inferred from source identifiers; individual story menu still needs verification.'}</p>${catalogTable('levels',s.level_ids.map(i=>W.levels.find(l=>l.id===i)).filter(Boolean))}</section>`}).join('')}${other.length?`<section class="rule-section"><h2>Packaged levels absent from the observed campaign menu</h2><p>These entries remain included for reference. Menu absence does not establish a release date.</p>${catalogTable('levels',other)}</section>`:''}${c.id==='campaign-3'?`<p>${esc(W.ui_observations.availability)}</p><a href="${APP_BASE.pathname}gameplay-evidence/campaign-3.png">Campaign 3 menu evidence</a>`:''}${source(c)}`}
function searchAll(){const groups=[['Buildings','buildings',uniq(D.buildings.filter(b=>!isSuppressed('buildings',b.gameobject_id)))],['Resources','resources',uniq(D.resources.filter(x=>x.publicly_named))],['Leaders','heroes',W.leaders],['Biomes','biomes',W.biomes],['Levels','levels',W.levels]],total=groups.reduce((n,[,,a])=>n+a.filter(matches).length,0);return `${header('Search',`${total} matches for “${query}”`,'CATALOG')}${groups.map(([title,type,items])=>{items=items.filter(matches);return items.length?`<h2>${title} <small class="small">${items.length}</small></h2>${catalogTable(type,items.slice(0,30))}`:''}).join('')}${total?'':empty()}`}
function availabilityRecord(type,o){
 const direct=V.entries.find(e=>e.id===o.id||e.name===o.name);
 if(direct)return direct;
 if(type==='levels'){const parent=V.entries.find(e=>e.associated_level_ids?.includes(o.id));if(parent)return {availability_status:'public_release_unconfirmed',note:'Associated with '+parent.name+' and packaged update '+parent.packaged_update_association+'. Public release is unconfirmed.',parent_evidence:parent}}
 if(type==='heroes'){const release=V.public_release_history.find(e=>e.id===o.name);if(release)return {...release,availability_status:'official_release_notes_evidence'}}
 return null;
}
function availability(type,o){const a=availabilityRecord(type,o);if(!a)return tag('Unknown','gray');if(a.availability_status==='user_reported_unreleased')return tag('Unreleased · user report','violet');if(a.availability_status==='official_release_notes_evidence')return tag('Released · official notes');return tag('Release unconfirmed','amber')}
function availabilitySection(type,o){const a=availabilityRecord(type,o);return `<section class="rule-section"><h2>Content availability</h2><div class="tags">${availability(type,o)}</div>${!a?'<p class="small">Presence in the installed files does not establish release or menu availability.</p>':a.availability_status==='user_reported_unreleased'?`<p class="small">Reported unreleased by the user as of ${esc(a.as_of)}. Packaged update ${a.packaged_update_association} text mentions ${esc(o.name)}; a public release date has not been established.</p>`:a.availability_status==='official_release_notes_evidence'?`<p class="small">Official release notes associate this story with update ${a.version}, dated ${esc(a.release_date)}. ${esc(a.date_note||'')} This is story/update evidence, not proof of this character’s first appearance.</p>`:`<p class="small">${esc(a.note||a.association_note||'Public release has not been established.')}</p>`}${o.name==='Oona'?`<p>${esc(W.ui_observations.availability)}</p><a href="${APP_BASE.pathname}gameplay-evidence/campaign-3.png">Observed campaign menu</a>`:''}${a?source(a,'Availability evidence'):''}</section>`}
function biomeRule(o){return N.biomes.find(b=>b.id===o.id)}
function assignedLink(item){const ref=item.wiki_refs?.find(r=>r.kind==='building');const b=ref?D.buildings.find(b=>b.source.path_id===ref.id||b.gameobject_id===ref.id):null;if(b)return `<a class="resource-link" href="${url('buildings',b.gameobject_id)}">${esc(item.name)}</a>`;const r=D.resources.find(r=>r.publicly_named&&(r.internal_name===item.name||r.name===item.name));return r?`<a class="resource-link" href="${url('resources',r.id)}">${esc(item.name)}</a>`:esc(item.name)}
function rawBiomeBody(o){const b=biomeRule(o);if(!b)return '<p>No biome configuration decoded.</p>';const list=(key)=>b[key]?.length?'<ul>'+b[key].map(x=>'<li>'+assignedLink(x)+'</li>').join('')+'</ul>':'<p class="small">Not established. An empty recovered list is not proof of absence.</p>';const sources=(b.resource_sources||[]).filter(x=>!/decoration|cosmetic/i.test(x.asset_path)&&!/fish/i.test(x.name));return `${o.id==='Winter'?observedBuilding({name:'Greenhouse'}):''}<div class="tags">${o.id==='Green'?tag('Default / baseline · user report'):tag('Compared with Evergreen','gray')}${tag(b.source?'Sandbox configuration':'No configuration decoded','gray')}</div><p class="small">These are sandbox biome assignments. Campaign and challenge maps may override available crops, sources and buildings.</p><div class="biome-lists"><section class="panel"><h2>Crops</h2>${list('crops')}${b.farming_context?`<p class="small">${esc(b.farming_context)}</p>`:''}</section><section class="panel"><h2>Orchard plants</h2>${list('orchard_plants')}</section><section class="panel"><h2>Forestry</h2>${list('forester_plants')}</section><section class="panel"><h2>Configured resource sources</h2>${sources.length?'<ul>'+sources.map(x=>'<li>'+assignedLink(x)+'</li>').join('')+'</ul>':'<p class="small">Resource sources are not established.</p>'}<p class="small">Actual yields and map-level availability are unverified. Decorative fish objects are excluded from resource claims.</p></section></div><section class="rule-section"><h2>Needs & hazards</h2>${b.special_needs_and_hazards?.length?b.special_needs_and_hazards.map(t=>`<div class="prose"><p>${rich(t.text)}</p></div>`).join(''):'<p class="small">No special need or hazard has been established from the recovered configuration.</p>'}</section><section class="rule-section"><h2>Biome buildings</h2>${list('placeables')}</section>${availabilitySection('biomes',o)}${source({source:b.source,scope:b.source_scope,limitations:b.limitations,assignments:b},'Biome assignment evidence')}`}
function biomeBacklinks(b){const related=N.biomes.filter(n=>['crops','orchard_plants','forester_plants','placeables'].some(k=>n[k]?.some(x=>x.wiki_refs?.some(ref=>ref.id===b.source.path_id||ref.id===b.gameobject_id))));return related.length?`<section class="rule-section"><h2>Biome assignments</h2><p class="small">Listed in these sandbox biome configurations; campaign and challenge availability may differ.</p><div class="reference-links">${related.map(n=>`<a href="${url('biomes',n.id)}">${esc(n.name)}</a>`).join('')}</div></section>`:''}

function observedBuilding(b){const o=W.ui_observations?.buildings[b.name];if(!o)return '';return `<section class="rule-section"><h2>In-game field guide</h2><p class="small">Version 30 · build 254 · 24 October 2026 · Counterspell field guide. Production cycles and timing remain untested.</p><ul>${o.claims.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>${o.discrepancy?notice('Recipe discrepancy',o.discrepancy):''}<a href="${APP_BASE.pathname}gameplay-evidence/${o.screenshot}">View field-guide screenshot</a></section>`}
function challengeObservations(){const o=W.ui_observations;if(!o)return '';return `<section class="rule-section"><h2>Six challenge types</h2><p>All six names were observed in the challenge archive. The examples below were checked against their briefings on ${o.date}; they are not universal rules for every challenge in a category.</p><div class="table-wrap"><table><thead><tr><th>Type</th><th>Example</th><th>Main objectives</th><th>Optional objectives</th><th>Day limit shown</th></tr></thead><tbody>${o.challenges.map(c=>`<tr><td>${esc(c.type)}</td><td><a href="${APP_BASE.pathname}gameplay-evidence/${c.screenshot}">${esc(c.name)}</a></td><td>${c.main.map(esc).join('<br>')}</td><td>${c.optional.map(esc).join('<br>')||'None displayed'}</td><td>${c.day_limit??'Not displayed'}</td></tr>`).join('')}</tbody></table></div>${o.challenges.map(c=>`<p><strong>${esc(c.type)}:</strong> ${esc(c.note)}</p>`).join('')}<p class="small">Archived leaderboard wording does not establish a currently active event. Scoring and completion behavior have not been tested.</p></section>`}

function scenarioAsset(x){if(!x)return '—';const b=B[x.gameobject_id],r=Rkey[x.localization_key];return b?`<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>`:r?`<a href="${url('resources',r.id)}">${esc(x.name)}</a>`:esc(x.name||x.guid||'Unresolved asset')}
function scenarioBacklinks(b){const maps=W.levels.filter(l=>l.scenario?.buildable_entries.some(x=>x.gameobject_id===b.gameobject_id));return maps.length?`<section class="rule-section" id="level-availability"><h2>${b.is_plant?'Where it can be planted':'Where it can be built'}</h2><p>Listed in the build or plant list of ${maps.length} level${maps.length>1?'s':''}, grouped by campaign and story.</p><p class="small">This exact definition appears in the stored build/plant lists below. Runtime unlocks and menu visibility remain untested.</p>${groupedLevels(maps)}</section>`:''}
function scenarioObjective(o){const kinds={Have:'Have',Create:'Create',Consume:'Consume / recycle',VillagerCount:'Population',Happiness:'Happiness',Extract:'Extract',Concern:'Need satisfaction',Housing:'Housing',HaveInBuilding:'Have in building',ReachDay:'Reach day',GearedPercentage:'Equipped villagers',UseSocialSpot:'Use social spot'},comparison={Equal:'=',NotEqual:'≠',Less:'<',LessOrEqual:'≤',Greater:'>',GreaterOrEqual:'≥'};const relevant=['Have','Create','Consume','Extract','HaveInBuilding','GearedPercentage','UseSocialSpot'].includes(o.condition_name);let target=relevant?scenarioAsset(o.target):o.condition_name==='Concern'?esc(o.concern_name):'—';if(o.condition_name==='HaveInBuilding')target+=' in '+scenarioAsset(o.building);return `<tr><td>${esc(kinds[o.condition_name]||o.condition_name)}</td><td>${target}</td><td>${esc(comparison[o.comparison_name]||o.comparison_name)} ${esc(o.NeededAmount)}</td></tr>`}
function levelBody(o){const s=o.scenario;if(!s)return legacyLevelBody(o);const cfg=s.level_config[0]||{},needs=[['Food','Food'],['Housing','Housing'],['Community','Community'],['Entertainment','Fun'],['Heat','Heat'],['Wellness','Wellness'],['Refreshment','Cooling'],['Hydration','Hydration / thirst']];const build=[...new Map(s.buildable_entries.map(x=>[x.guid,x])).values()],plants=build.filter(x=>B[x.gameobject_id]?.is_plant||x.localization_key?.startsWith('Plant.')),other=build.filter(x=>!plants.includes(x));const objectiveTable=secondary=>{const os=s.objectives.filter(x=>x.IsSecondary===secondary);return os.length?`<div class="table-wrap"><table><thead><tr><th>Condition</th><th>Target</th><th>Required value</th></tr></thead><tbody>${os.map(scenarioObjective).join('')}</tbody></table></div>`:'<p>No objectives in this group are stored.</p>'};const assetList=items=>items.length?'<ul>'+items.map(x=>'<li>'+scenarioAsset(x)+'</li>').join('')+'</ul>':'<p>No entries in this group.</p>';return `<div class="prose"><p>${rich(o.description)}</p></div><div class="tags">${tag('Decoded scenario')}${tag('Objectives cross-checked')}</div><p class="small">Stored map configuration for version 30, build 254. Packaged content does not establish live menu availability.</p><div class="fact-grid"><div class="fact"><small>Main objectives</small><b>${s.primary_objective_count}</b></div><div class="fact"><small>Optional objectives</small><b>${s.optional_objective_count}</b></div><div class="fact"><small>Day limit</small><b>${s.day_limit===-1?'No limit stored':s.day_limit===null?'Unspecified':s.day_limit+' days'}</b></div></div><section class="rule-section"><h2>Main objectives</h2>${objectiveTable(false)}<h2>Optional objectives</h2>${objectiveTable(true)}<p class="small">Values and comparisons match both the header and world records. Satisfaction, housing and equipment values are stored thresholds; their UI wording may differ. “Consume / recycle” is an internal condition whose wording depends on the target.</p></section><section class="rule-section"><h2>Villager needs</h2><div class="table-wrap"><table><thead><tr><th>Need</th><th>Scenario setting</th></tr></thead><tbody>${needs.map(([key,label])=>{const k='IsConcern'+key+'Available';return `<tr><td>${label}</td><td>${Object.hasOwn(cfg,k)?cfg[k]?'Enabled':'Disabled':'Unspecified in this file'}</td></tr>`}).join('')}</tbody></table></div><p class="small">An absent field in an older map is not treated as disabled. Runtime defaults and migration remain unverified.</p></section><section class="rule-section"><h2>Available buildings & plants</h2><p>${build.length} distinct configured entries (${s.buildable_entries.length} stored entries including duplicates). These are the scenario’s build/plant list; later unlocks and current UI visibility have not been tested.</p><div class="biome-lists"><section class="panel"><h3>Buildings, structures & decorations</h3>${assetList(other)}</section><section class="panel"><h3>Fields & plants</h3>${assetList(plants)}</section></div></section><section class="rule-section"><h2>Starting objects & resources</h2><p class="small">Counts below are serialized prefab entities. They do not establish harvest yields, stockpile units, or numbers of independent buildings; child entities and internal objects can be included.</p><details><summary>Show ${s.initial_prefab_instances.length} starting object types</summary><div class="table-wrap"><table><thead><tr><th>Object</th><th>Stored entities</th></tr></thead><tbody>${s.initial_prefab_instances.map(x=>`<tr><td>${scenarioAsset(x)}</td><td>${x.instance_count}</td></tr>`).join('')}</tbody></table></div></details></section>${source({text_asset_id:s.text_asset_id,source_level_path:s.source_level_path,sha256:s.sha256,world_objectives_match_header:s.world_objectives_match_header,level_config:s.level_config},'Scenario decoding evidence')}<section class="rule-section"><h2>Remaining checks</h2>${checks(['Confirm current menu category and release availability.','Check runtime unlocks and defaults for need fields absent in legacy maps.','Measure yields, need decay, production rates and other runtime effects.'])}</section>`}

function scenarioNeedSummary(s){const labels={Food:"Food",Housing:"Housing",Community:"Community",Entertainment:"Fun",Heat:"Heat",Wellness:"Wellness",Refreshment:"Cooling",Hydration:"Hydration"};return Object.entries(s.level_config[0]||{}).filter(([k,v])=>k.startsWith("IsConcern")&&v===true).map(([k])=>labels[k.slice(9,-9)]||k).join(", ")||"None stored"}

function biomeBody(o){const b=biomeRule(o);return `${o.id==='Winter'?observedBuilding({name:'Greenhouse'}):''}<section class="rule-section"><h2>Needs & environment</h2>${(b?.special_needs_and_hazards||[]).map(t=>`<p>${rich(t.text)}</p>`).join('')||'<p>See individual scenarios for their enabled needs.</p>'}</section><section class="rule-section"><h2>Plants & buildings</h2><p>Available plants and buildings depend on the scenario. Each scenario page lists its own planting and building options.</p><a href="${url('levels')}">Browse scenarios</a></section>${source(b,'Sandbox biome data — interpretation under review')}`;}
// Reader pages and research pages share one source renderer; research material is moved, not discarded.
function rawArticle(type,id){if(type==='buildings')return buildingPage(B[id]);if(type==='resources')return resourcePage(R[id]);if(type==='chains')return chainPage(B[id]);const list=type==='heroes'?W.leaders:W[type];return worldPage(type,list.find(x=>String(x.id)===String(id)))}
function pullBlocks(html,tagName,predicate){const re=new RegExp('<\\/?'+tagName+'\\b[^>]*>','gi'),stack=[],spans=[];let m;while((m=re.exec(html))){if(m[0].startsWith('</')){const begin=stack.pop();if(begin!==undefined){const text=html.slice(begin,re.lastIndex);if(predicate(text))spans.push([begin,re.lastIndex,text])}}else stack.push(m.index)}const top=spans.filter(s=>!spans.some(p=>p!==s&&p[0]<s[0]&&p[1]>=s[1])).sort((a,b)=>a[0]-b[0]);let clean='',pos=0;for(const [start,end]of top){clean+=html.slice(pos,start);pos=end}clean+=html.slice(pos);return {html:clean,blocks:top.map(x=>x[2])}}
function splitResearch(html){let notes=[];for(const [tag,pred] of [['details',s=>/^<details\b[^>]*class="source"/.test(s)],['aside',s=>/^<aside\b[^>]*class="detail-aside"/.test(s)],['section',s=>/^<section\b[^>]*>\s*<h2>(Pending verification|Gameplay checks|Remaining checks|What still needs checking|Biome assignments|Sandbox biome references|Content availability)<\/h2>/.test(s)],['div',s=>/^<div\b[^>]*class="notice\b/.test(s)]]){const out=pullBlocks(html,tag,pred);html=out.html;notes.push(...out.blocks)}
 const paragraphs=pullBlocks(html,'p',s=>/^<p\b[^>]*class="small"/.test(s)&&/verif|not tested|untested|decoded|stored map configuration|runtime|source tables|internal condition|not establish/i.test(s));html=paragraphs.html;notes.push(...paragraphs.blocks);
 html=html.replace(/<span class="tag[^"\n]*">(?:Needs gameplay verification|Decoded[^<]*|Recovered[^<]*|Objectives cross-checked|Unknown|Release unconfirmed|Sandbox configuration|No configuration decoded|Derived from[^<]*|Game text)<\/span>/g,'').replace(/<div class="tags">\s*<\/div>/g,'').replace(/<div><dt>(?:Work range \(raw units\)|Work schedule \(raw cycle\)|Gameplay verification|Game verification|Objective quantities|Internal name|Data version|Packaged map)<\/dt><dd>[\s\S]*?<\/dd><\/div>/g,'');
 return {html,notes};}
function readerArticle(html,type,id){const {html:clean}=splitResearch(html);const rec=pageLookup[type+'/'+id];return clean+`<p class="article-evidence-link"><a href="${url('evidence',type+'/'+id)}">Sources & research notes for this page</a></p>`+contributionLinks(type,id,rec?.name||'')}
function researchPage(id){const slash=id.indexOf('/'),type=id.slice(0,slash),key=id.slice(slash+1),rec=pageLookup[type+'/'+key];if(!rec)return empty();const original=rawArticle(type,key),split=splitResearch(original);let extra='';if(type==='buildings'){const b=B[key];extra=source({work_schedule:b.workplace_config?.WorkTimeRange,interpretation:'Normalized work-cycle interval; time origin and clock mapping unverified.'},'Work schedule fields');if(b.is_plant)extra+=biomeResearch(b);if(b.name==='Clay Pit')extra+=`<h2>Do clay workers sleep in?</h2><p>The Clay Pit stores a work interval of 0 → 0.6; Farm stores 0.9 → 0.5 and Quarry 0 → 0.5. This establishes different work schedules, but sleep duration and the clock-time mapping have not been verified.</p>`;}
 return `${header(rec.name+' — sources & research','Evidence, decoding details and open questions for this article.','RESEARCH')}<p><a href="${url(type,key)}">← ${esc(rec.name)}</a></p>${split.notes.join('')}${extra}${contributionNotes(type,key)}`;}
function biomeResearch(b){const related=N.biomes.filter(n=>['crops','orchard_plants','forester_plants','placeables'].some(k=>n[k]?.some(x=>x.wiki_refs?.some(ref=>ref.id===b.source.path_id||ref.id===b.gameobject_id))));return `<section class="rule-section"><h2>Sandbox biome references</h2><p>These are references in sandbox configuration, not a verified crop-availability table. Shared defaults, exclusions, farm compatibility and runtime filtering still need interpretation.</p><ul>${related.map(n=>`<li>${esc(n.name)}</li>`).join('')}</ul>${source(related.map(n=>({biome:n.name,source:n.source,assignments:n.crops,exclusions:n.excluded_base_placeables})),'Sandbox assignment records')}</section>`}
function cropPage(b){const maps=W.levels.filter(l=>l.scenario?.buildable_entries.some(x=>x.gameobject_id===b.gameobject_id));const farm=D.buildings.find(x=>x.name==='Farm');return `${crumbs('buildings',b.name)}<div class="detail-head"><div class="detail-icon">${icon('buildings',b)}</div><div><p class="eyebrow">PLANT</p><h1>${esc(b.name)}</h1></div></div><article>${buildingInfobox(b)}${verifyBadge('buildings',b.gameobject_id)}<p>${b.paths.some(p=>p.includes('/orchard/'))?'An orchard plant.':b.paths.some(p=>p.includes('/forester/'))?'A forestry plant.':'A plantable field.'}</p>${b.description?`<div class="prose"><p>${rich(b.description)}</p></div>`:''}${b.paths.some(p=>p.includes('/buildings/field/'))&&farm?`<p>See the <a href="${url('buildings',farm.gameobject_id)}">Farm</a> for planting and harvesting.</p>`:''}${maps.length?scenarioBacklinks(b):'<section class="rule-section"><h2>Where it can be planted</h2><p>No matching scenario planting list was found.</p></section>'}${source(b,'Plant definition')}${biomeResearch(b)}${navbox('buildings',b)}</article>`}
function friendlyTerm(key){const base=key.split('.').slice(0,2).join('.'),plural=/Plural/.test(key);return W.terms?.[key]||W.terms?.[base+(plural?'.NamePlural':'.Name')]||null}
function rich(s){return esc(s||'').replace(/&lt;\/?(?:style(?:=[^&]*?)?|size(?:=[^&]*?)?)&gt;/g,'').replace(/&lt;(\/?)b&gt;/g,'<$1strong>').replace(/\n/g,'<br>').replace(/\{([^}]+)\}|\[((?:Resource|Building|Sources|Field|Tree)\.[^\]]+)\]/g,(_,a,b)=>{const key=a||b,base=key.split('.').slice(0,2).join('.'),label=friendlyTerm(key);if(Bkey[base])return `<a class="resource-link" href="${url('buildings',Bkey[base].gameobject_id)}">${esc(Bkey[base].name)}</a>`;if(Rkey[base])return `<a class="resource-link" href="${url('resources',Rkey[base].id)}">${esc(label||Rkey[base].name)}</a>`;if(label)return esc(label);if(/count|amount|days|value|percentage/i.test(key))return 'target quantity';return esc(key.replace(/\.(WithIconPlural|WithIcon|NamePlural|Name)$/,'').split('.').at(-1).replace(/([a-z])([A-Z])/g,'$1 $2'))})}

function contributionNotes(type,id){const rows=(W.contributions||[]).filter(x=>x.target.type===type&&String(x.target.id)===String(id));return rows.length?`<section class="rule-section"><h2>Contributed observations</h2>${rows.map(x=>`<article><h3>${esc(x.claim)}</h3><p>Status: ${esc(x.status)} · ${esc(x.evidence.kind)} · ${esc(x.evidence.game_version)}</p><p>${esc(x.evidence.reference)}</p><p>${esc(x.notes||'')}</p></article>`).join('')}</section>`:''}
function contributionPage(){function inline(s){return esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\((https:\/\/[^)]+)\)/g,'<a href="$2">$1</a>')}let html='',list='';for(const line of W.contribution_guide.split('\n')){const ordered=/^\d+\. /.test(line),bullet=/^- /.test(line);if(!ordered&&!bullet&&list){html+=`</${list}>`;list=''}if(/^# /.test(line)){html+=header(line.slice(2),'Help improve a sourced, community-maintained reference.','CONTRIBUTE')}else if(/^## /.test(line)){html+=`<h2>${inline(line.slice(3))}</h2>`}else if(ordered||bullet){const wanted=ordered?'ol':'ul';if(list!==wanted){if(list)html+=`</${list}>`;html+=`<${wanted}>`;list=wanted}html+=`<li>${inline(line.replace(/^(?:- |\d+\. )/,''))}</li>`}else if(line.trim())html+=`<p>${inline(line)}</p>`}if(list)html+=`</${list}>`;return '<div class="prose contribution-guide">'+html+'</div>'}

let fullWorld,publicWorld,fullBiomes,publicBiomes,fullRules,publicRules;
function spoilerEntry(type,id){if(type==='chains')type='buildings';const entries=(fullWorld||W)?.spoiler_policy?.entries||[];return entries.find(x=>x.type===type&&String(x.id)===String(id));}
function initializeSpoilers(){fullRules=D;fullWorld=W;fullBiomes=N;publicRules={...D,buildings:D.buildings.filter(b=>!spoilerEntry('buildings',b.gameobject_id)&&!isSuppressed('buildings',b.gameobject_id)),resources:D.resources.filter(r=>!spoilerEntry('resources',r.id))};publicWorld={...W,levels:W.levels.filter(x=>!spoilerEntry('levels',x.id)),leaders:W.leaders.filter(x=>!spoilerEntry('heroes',x.id)),biomes:W.biomes.filter(x=>!spoilerEntry('biomes',x.id)),campaigns:W.campaigns.map(x=>({...x,level_ids:x.level_ids.filter(id=>!spoilerEntry('levels',id))})),stories:W.stories.filter(x=>!W.spoiler_policy.entries.some(e=>e.type==='heroes'&&(x.id===W.leaders.find(l=>l.id===e.id)?.name||x.name.includes(W.leaders.find(l=>l.id===e.id)?.name)))),ui_observations:{...W.ui_observations,availability:'Additional packaged content is listed separately in the Spoilers section.'}};publicBiomes={...N,biomes:N.biomes.filter(x=>!spoilerEntry('biomes',x.id))};}
function applySpoilerScope(type,id){const research=type==='evidence'?spoilerEntry(id.split('/')[0],id.slice(id.indexOf('/')+1)):null;const allow=type==='spoilers'||spoilerEntry(type,id)||research;W=allow?fullWorld:publicWorld;N=allow?fullBiomes:publicBiomes;D=allow?fullRules:publicRules;}
function spoilerWarning(type,id){const e=spoilerEntry(type,id);return `<aside class="notice"><div><strong>Spoilers: unreleased or release-unconfirmed content</strong><p>${esc(e.reason)} Status recorded ${esc(e.as_of)}.</p><a href="${url('spoilers')}">Spoiler index</a> · <a href="${url('')}">Return to the regular guide</a></div></aside>`;}
function spoilersHomeSection(){return `<section class="rule-section spoiler-home"><h2>Spoilers</h2><p>Looking to look ahead? Check out the spoilers section.</p><a href="${url('spoilers')}">Browse Spoilers →</a></section>`;}
function spoilersPage(){return `${header('Spoilers','This section contains reported-unreleased content and closely associated material whose release is unconfirmed. Names and details below may spoil future updates.','OPTIONAL CONTENT')}<p>Placement here is editorial; it does not establish a release date. Other entries with unknown release status are not automatically treated as unreleased.</p><p><a href="${url('')}">Return to the regular guide</a></p>${['resources','buildings','chains','heroes','levels','biomes'].map(type=>{const entries=fullWorld.spoiler_policy.entries.filter(x=>x.type===type);return `<section class="rule-section"><h2>${({resources:'Resources & food',buildings:'Buildings',chains:'Production chains',heroes:'Leaders',levels:'Scenarios',biomes:'Biomes'})[type]}</h2><ul>${entries.map(e=>{const obj=(['buildings','chains'].includes(type)?fullRules.buildings:type==='resources'?fullRules.resources:type==='heroes'?fullWorld.leaders:fullWorld[type]).find(x=>String(x.gameobject_id||x.id)===String(e.id));return `<li><a href="${url(type,e.id)}">${esc(obj.name)}</a> — ${esc(e.status==='reported-unreleased'?'Reported unreleased':'Related content; release unconfirmed')}<p>${esc(e.reason)}</p></li>`}).join('')}</ul></section>`}).join('')}`;}

// Companion-layer helpers: infoboxes, backlinks, grouped availability, story context, navboxes and contribution links.
const GITHUB='https://github.com/kellan/outlanders2-wiki';
const CATEGORY_LABELS={production:'Production building',homes:'Housing',fields:'Field or plant',other:'Structure or decoration'};
function contentFile(type,id){const folder={buildings:'buildings',chains:'buildings',resources:'resources',levels:'scenarios',heroes:'leaders',biomes:'biomes'}[type];return folder?`content/${folder}/${id}.json`:null}
function storyOf(levelId){return W.stories.find(s=>s.level_ids?.includes(levelId))}
function campaignOf(levelId){return W.campaigns.find(c=>c.level_ids.includes(levelId))}
function levelLink(l,extra=''){return `<a href="${url('levels',l.id)}">${esc(l.name)}</a>${extra}`}
function levelGroups(levels,extra=()=>''){
 const byId=new Map(levels.map(l=>[l.id,l]));const groups=[];const seen=new Set();
 for(const c of W.campaigns){const stories=W.stories.filter(s=>s.campaign_id===c.id).sort((a,b)=>a.menu_order-b.menu_order);const rows=[];
  for(const s of stories){const hits=(s.level_ids||[]).filter(i=>byId.has(i));if(!hits.length)continue;hits.forEach(i=>seen.add(i));rows.push(`<li><strong>${esc(s.name)}</strong>: ${hits.map(i=>levelLink(byId.get(i),extra(byId.get(i)))).join(', ')}</li>`)}
  const loose=c.level_ids.filter(i=>byId.has(i)&&!seen.has(i));if(loose.length){loose.forEach(i=>seen.add(i));rows.push(`<li><strong>Other levels</strong>: ${loose.map(i=>levelLink(byId.get(i),extra(byId.get(i)))).join(', ')}</li>`)}
  if(rows.length)groups.push({title:`<a href="${url('campaigns',c.id)}">${esc(c.name)}</a>`,html:`<ul class="level-groups">${rows.join('')}</ul>`,count:rows.length})}
 const rest=levels.filter(l=>!seen.has(l.id)),named=rest.filter(l=>!/^Unnamed scenario/.test(l.name)&&l.category!=='tournament_tutorial'),tutorials=rest.filter(l=>l.category==='tournament_tutorial'),unnamed=rest.filter(l=>/^Unnamed scenario/.test(l.name)&&l.category!=='tournament_tutorial');
 const links=ls=>`<div class="reference-links">${ls.sort((a,b)=>a.name.localeCompare(b.name)).map(l=>levelLink(l,extra(l))).join('')}</div>`;
 if(named.length)groups.push({title:'Standalone &amp; challenge maps',html:links(named)});
 if(tutorials.length)groups.push({title:'Tutorials',html:links(tutorials)});
 if(unnamed.length)groups.push({title:'',html:`<details><summary>${unnamed.length} unnamed archive map${unnamed.length>1?'s':''}</summary>${links(unnamed)}</details>`});
 return groups;
}
function groupedLevels(levels,extra){return levelGroups(levels,extra).map(g=>`${g.title?`<h3>${g.title}</h3>`:''}${g.html}`).join('')}
function objectiveTargets(predicate){const rows=[];for(const l of W.levels){const os=(l.scenario?.objectives||[]).filter(o=>['Have','Create','Consume','Extract','HaveInBuilding','GearedPercentage','UseSocialSpot'].includes(o.condition_name)&&predicate(o));if(os.length)rows.push({level:l,objectives:os})}return rows}
function objectiveText(o){const kinds={Have:'Have',Create:'Create',Consume:'Consume',Extract:'Extract',HaveInBuilding:'Have in building',GearedPercentage:'Equipped villagers',UseSocialSpot:'Use'},comparison={Equal:'=',NotEqual:'≠',Less:'<',LessOrEqual:'≤',Greater:'>',GreaterOrEqual:'≥'};return `${kinds[o.condition_name]||o.condition_name} ${comparison[o.comparison_name]||''} ${fmt(o.NeededAmount)}${o.IsSecondary?' (optional)':''}`}
function objectiveBacklinks(label,rows){if(!rows.length)return '';const byId=new Map(rows.map(r=>[r.level.id,r]));return `<section class="rule-section"><h2>Level objectives that need ${esc(label)}</h2><p class="small">Stored objective thresholds for ${rows.length} level${rows.length>1?'s':''}.</p>${groupedLevels(rows.map(r=>r.level),l=>` <span class="objective-note">${byId.get(l.id).objectives.map(objectiveText).map(esc).join('; ')}</span>`)}</section>`}
function growthFor(b){const norm=s=>String(s).replace(/^Field\s*/,'').replace(/\s*Sapling\s*/,'').replace(/\s+/g,'').toLowerCase();return D.growth?.find(g=>norm(g.name)===norm(b.internal_name))}
function infobox(type,o,rows,image){const body=rows.filter(r=>r&&r[1]!==null&&r[1]!==undefined&&r[1]!=='').map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join('');return `<aside class="infobox"><div class="infobox-image">${image}</div><h3 class="infobox-title">${esc(o.name)}</h3><dl>${body}</dl></aside>`}
function buildingInfobox(b){const cat=category(b),recipe=b.derived_recipes.find(r=>!r.caveats.length),guide=W.ui_observations?.buildings?.[b.name],maps=W.levels.filter(l=>l.scenario?.buildable_entries.some(x=>x.gameobject_id===b.gameobject_id)),growth=growthFor(b);
 const plantKind=b.paths.some(p=>p.includes('/orchard/'))?'Orchard plant':b.paths.some(p=>p.includes('/forester/'))?'Forestry plant':'Field crop';
 return infobox('buildings',b,[['Type',b.is_plant?plantKind:CATEGORY_LABELS[cat]],['Footprint',!b.is_plant&&b.dimensions?`${fmt(b.dimensions.x)} × ${fmt(b.dimensions.z)}`:null],['Cost',!b.is_plant&&b.construction?.material_inputs.length?inlineAmounts(b.construction.material_inputs):null],['Workers',b.max_workers],['Houses',b.sleep_spots!==null?`${b.sleep_spots} villagers`:null],['Needs',recipe?inlineAmounts(recipe.inputs):null],['Produces',recipe?inlineAmounts(recipe.outputs):b.formula_ids.length?`<a href="${url('chains',b.gameobject_id)}">See production chain</a>`:null],['Growth',growth?`${growth.total_configured_stage_days} stored stage days`:null],['Levels',maps.length?`<a href="#level-availability">${maps.length} level${maps.length>1?'s':''}</a>`:null]],icon('buildings',b))}
function resourceInfobox(r,producing,using,costs,objectives){const vals=Object.entries(r.need_units).filter(([,v])=>v!==0);const list=bs=>uniq(bs).slice(0,6).map(b=>`<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>`).join(', ')+(uniq(bs).length>6?` and ${uniq(bs).length-6} more`:'');
 return infobox('resources',r,[['Type',r.publicly_named?(r.need_units.FoodUnits>0?'Food':'Resource'):'Intermediate'],['Satisfies',vals.length?vals.map(([k,v])=>`${esc(k.replace('Units',''))} ${fmt(v)}`).join(', '):null],['Produced by',producing.length?list(producing):null],['Used by',using.length?list(using):null],['Builds',costs.length?list(costs):null],['Objectives',objectives.length?`<a href="#objective-backlinks">${objectives.length} level${objectives.length>1?'s':''}</a>`:null]],icon('resources',r))}
function verifyBadge(type,id,extra=''){return `<p class="verify-badge"><span>Game data v30 · build 254</span>${extra}<a href="${url('evidence',type+'/'+id)}">Sources &amp; research notes</a></p>`}
function contributionLinks(type,id,name){const file=contentFile(type,id);if(!file)return '';const spoiler=!!spoilerEntry(type,id);const title=encodeURIComponent(spoiler?'Correction for a spoiler entry':`Correction: ${name}`);return `<p class="article-actions"><a href="${GITHUB}/edit/main/${file}">Suggest an edit</a><a href="${GITHUB}/issues/new?template=content-correction.md&amp;title=${title}">Report a problem</a><a href="${GITHUB}/blob/main/CONTRIBUTING.md">How contributions work</a></p>`}
function navboxList(label,items,type){return items.length?`<div class="navbox-row"><span class="navbox-label">${label}</span><ul>${items.map(o=>`<li><a href="${url(type,o.gameobject_id||o.id)}">${esc(o.name)}</a></li>`).join('')}</ul></div>`:''}
function navbox(type,o){const sorted=xs=>[...xs].sort((a,b)=>a.name.localeCompare(b.name));let title='',rows='';
 if(type==='buildings'||type==='chains'){const cat=category(o);const same=uniq(D.buildings.filter(b=>!isSuppressed('buildings',b.gameobject_id)&&!b.is_plant&&category(b)===cat));title=CATEGORY_LABELS[cat]+'s';if(o.is_plant){const plants=uniq(D.buildings.filter(b=>b.is_plant&&!isSuppressed('buildings',b.gameobject_id)&&b.name!=='Template'));title='Fields & plants';rows=navboxList('Crops',sorted(plants.filter(p=>p.paths.some(x=>x.includes('/buildings/field/')))),'buildings')+navboxList('Orchard',sorted(plants.filter(p=>p.paths.some(x=>x.includes('/orchard/')))),'buildings')+navboxList('Forestry',sorted(plants.filter(p=>p.paths.some(x=>x.includes('/forester/')))),'buildings')}else rows=navboxList(title,sorted(same),'buildings')}
 if(type==='resources'){const food=o.publicly_named&&o.need_units.FoodUnits>0;const items=uniq(D.resources.filter(r=>r.publicly_named&&(food?r.need_units.FoodUnits>0:r.need_units.FoodUnits===0)));title=food?'Food':'Resources';rows=navboxList(title,sorted(items),'resources')}
 if(type==='heroes'){title='Leaders';rows=navboxList('Leaders',sorted(W.leaders),'heroes')}
 if(type==='biomes'){title='Biomes';rows=navboxList('Biomes',sorted(W.biomes),'biomes')}
 if(type==='levels'){const s=storyOf(o.id),c=campaignOf(o.id);if(s&&c){title=esc(c.name);rows=navboxList(esc(s.name),s.level_ids.map(i=>W.levels.find(l=>l.id===i)).filter(Boolean),'levels');const others=W.stories.filter(x=>x.campaign_id===c.id&&x!==s).sort((a,b)=>a.menu_order-b.menu_order);rows+=others.length?`<div class="navbox-row"><span class="navbox-label">Other stories</span><ul>${others.map(x=>`<li><a href="${url('campaigns',c.id)}">${esc(x.name)}</a></li>`).join('')}</ul></div>`:''}}
 return rows?`<nav class="navbox" aria-label="Related pages"><h2>${title}</h2>${rows}</nav>`:''}
function storyContext(o){const s=storyOf(o.id),c=campaignOf(o.id);if(!s||!c)return o.category==='tournament_tutorial'?'<p class="story-context">Tournament tutorial level.</p>':'';const ids=s.level_ids,pos=ids.indexOf(o.id),prev=pos>0?W.levels.find(l=>l.id===ids[pos-1]):null,next=pos<ids.length-1?W.levels.find(l=>l.id===ids[pos+1]):null,leader=W.leaders.find(l=>l.name===s.leader_name);
 return `<div class="story-context"><p><a href="${url('campaigns',c.id)}">${esc(c.name)}</a> › <strong>${esc(s.name)}</strong> · Level ${pos+1} of ${ids.length}${leader?` · Leader: <a href="${url('heroes',leader.id)}">${esc(leader.name)}</a>`:''}</p><p class="story-nav">${prev?`<a href="${url('levels',prev.id)}">← ${esc(prev.name)}</a>`:'<span></span>'}${next?`<a href="${url('levels',next.id)}">${esc(next.name)} →</a>`:''}</p></div>`}
function leaderStories(o){const stories=W.stories.filter(s=>s.leader_name===o.name&&s.level_ids?.length).sort((a,b)=>a.campaign_id.localeCompare(b.campaign_id)||a.menu_order-b.menu_order);if(!stories.length)return '';return `<section class="rule-section"><h2>Stories &amp; levels</h2>${stories.map(s=>{const c=W.campaigns.find(c=>c.id===s.campaign_id);return `<h3>${esc(s.name)}${c?` <small class="small"><a href="${url('campaigns',c.id)}">${esc(c.name)}</a></small>`:''}</h3><ol class="story-levels">${s.level_ids.map(i=>W.levels.find(l=>l.id===i)).filter(Boolean).map(l=>`<li>${levelLink(l)}${l.scenario?` <span class="objective-note">${l.scenario.primary_objective_count} main objective${l.scenario.primary_objective_count===1?'':'s'}${l.scenario.day_limit>0?` · ${l.scenario.day_limit} days`:''}</span>`:''}</li>`).join('')}</ol>`}).join('')}</section>`}
